        cryo_sceptre: SCIFI_DIR + 'forceField_001.ogg',
        solar_lance: SCIFI_DIR + 'laserLarge_003.ogg',
        apothicon_servant_bo3: SCIFI_DIR + 'lowFrequency_explosion_000.ogg',
